  [79976] = { "きっとここだ", "ここに誰がいたにせよ、ちょうど行き違いになったようだ。", "「そういうわけで、仕事をまた地下に戻すことにした。悪い連中の手に渡らないようにな」\n\n<紙はちょうどこの伝言が収まる大きさに破り取られている。これが書き手から読む最後の言葉なのか、それとも次の隠れ家への手がかりなのか、あなたには分からない。きちんと留められていなかった寝袋が、あなたの足元へ広がってくる……>", nil, nil, 0x3d8d005f, 0x5d8a5aef, 0xb96b3437, nil, nil, "...mm" },
